<?php
/**
 * Plugin Name: Reinforce Lab Redirects (A4)
 * Description: Applies the approved redirect map (D-181) from core/reinforce-redirects-map.php, which is generated by claude/tools/redirects.py from claude/data/redirect-map-draft.csv. 301s apply first, before WordPress's own canonical redirect, and go straight to the final page (one hop). 410s apply only when WordPress would otherwise answer 404 (or for an approved feed address), so a removal can never hide a page that exists; the visitor sees the normal not-found page with status 410. Query strings (for example ?add-to-cart=) are dropped on redirect. Author archives and /paged-N/ junk are handled in blog/reinforce-blog.php.
 */
if (!defined('ABSPATH')) exit;

require_once __DIR__ . '/reinforce-redirects-map.php';

function rl_redirect_path() {
    $uri = isset($_SERVER['REQUEST_URI']) ? (string) $_SERVER['REQUEST_URI'] : '/';
    $path = rawurldecode((string) parse_url($uri, PHP_URL_PATH));
    $path = '/' . ltrim(preg_replace('#/+#', '/', $path), '/');
    // pages end with a slash; files (with an extension) do not
    if (substr($path, -1) !== '/' && !preg_match('#\.[a-z0-9]{2,5}$#i', $path)) $path .= '/';
    return strtolower($path);
}

/* approved removals that do not depend on one path: /paged-N/ junk anywhere (F-001) and old WooCommerce
   checkout calls (?wc-ajax=..., no shop on the new site, D-148). Answered as early as possible, before
   any other plugin (Yoast sends retired author pages home) can redirect them. */
add_action('wp', function () {
    if (is_admin() || wp_doing_ajax() || (defined('REST_REQUEST') && REST_REQUEST)) return;
    if (!preg_match('#/paged-\d+/#', rl_redirect_path()) && !isset($_GET['wc-ajax'])) return;
    rl_gone();
    $t = get_query_template('404');
    if ($t) include $t;
    exit;
}, -100);

add_action('template_redirect', function () {
    if (is_admin() || wp_doing_ajax() || (defined('REST_REQUEST') && REST_REQUEST)) return;
    $rules = rl_redirect_rules();
    $path = rl_redirect_path();
    if (isset($rules['301'][$path])) {
        $t = $rules['301'][$path];
        $to = preg_match('#^https?://#', $t) ? $t : home_url($t);
        wp_safe_redirect($to, 301, 'Reinforce Lab redirects');
        exit;
    }
    // 410 only where WordPress has no page; feeds of kept posts are also approved 410 (they exist automatically)
    if ((is_404() || is_feed()) && isset($rules['410'][$path])) {
        rl_gone();
    }
    // kept addresses that production already answers 404 (for example /project/inpace/): stay 404, no guessed redirect
    if (is_404() && isset($rules['404'][$path])) {
        remove_action('template_redirect', 'redirect_canonical');
    }
}, 0);

/* approved 410 sitemap files of the closed shop (/product-sitemap.xml, D-148): answered before Yoast's sitemap router */
add_action('parse_request', function () {
    $path = rl_redirect_path();
    if (substr($path, -4) !== '.xml') return;
    $rules = rl_redirect_rules();
    if (!isset($rules['410'][$path])) return;
    status_header(410);
    nocache_headers();
    header('Content-Type: text/plain; charset=utf-8');
    echo 'Gone';
    exit;
}, 0);

/* the old WooCommerce REST routes (/wp-json/wc/..., no shop on the new site, D-148) answer 410 */
add_filter('rest_pre_dispatch', function ($result, $server, $request) {
    if (strpos((string) $request->get_route(), '/wc/') !== 0) return $result;
    return new WP_Error('rl_gone', 'Gone', ['status' => 410]);
}, 999, 3);

/* category links (blog chips, post kickers, breadcrumbs) point straight to where a retired category archive now
   goes, so the site never links to its own redirect (A4 internal link scan). Live categories are unchanged. */
add_filter('category_link', function ($link, $term_id) {
    $path = strtolower('/' . trim((string) wp_parse_url($link, PHP_URL_PATH), '/') . '/');
    $t = get_term($term_id, 'category');
    if ($t && !is_wp_error($t) && $t->slug === 'uncategorized') return home_url('/blog/');  // D-144: 301 to /blog/
    $rules = rl_redirect_rules();
    if (isset($rules['301'][$path])) {
        $to = $rules['301'][$path];
        return preg_match('#^https?://#', $to) ? $to : home_url($to);
    }
    if (isset($rules['410'][$path])) return home_url('/blog/');
    return $link;
}, 999, 2);

/* 410 Gone with the site's normal not-found page; no "guess a nearby page" redirect afterwards */
function rl_gone() {
    global $wp_query;
    remove_action('template_redirect', 'redirect_canonical');
    add_filter('wpseo_premium_redirects_enabled', '__return_false');
    if ($wp_query) $wp_query->set_404();
    status_header(410);
    nocache_headers();
    if (is_feed() || isset($_GET['wc-ajax'])) { header('Content-Type: text/plain; charset=utf-8'); echo 'Gone'; exit; }
}
